  L5SAR.ek L ar LB FF sp scr [(PMSPA.o_src PMB.AD fb + 256, 40)] M2 M3 -> mem_grows M2 M3 ->
  PM.parser_at RSEGS PMB.AD PMSPA.accA PMSPA.annA M2 (PMSPA.o_p PMB.AD fb) ois s ->
  L5.u64_at RSEGS M3 (PMSPA.o_src PMB.AD fb + 264) (PM.sr_qc (PM.p_src s)) -> L5.u64_at RSEGS M3 (PMSPA.o_src PMB.AD fb + 272) PM.CHUNK ->
  L5.u64_at RSEGS M3 (PMSPA.o_src PMB.AD fb + 280) de' -> L5.u64_at RSEGS M3 (PMSPA.o_src PMB.AD fb + 288) rem' ->
  PM.sr_qc (PM.p_src s) <= de' -> 0 <= rem' -> de' + rem' <= PM.sr_qc (PM.p_src s) + PM.CHUNK ->
  PM.parser_at RSEGS PMB.AD PMSPA.accA PMSPA.annA M3 (PMSPA.o_p PMB.AD fb) ois (PMSPA.with_src s (PM.SRC (PM.sr_qc (PM.p_src s)) de' rem')).
Proof.
